    "Topic": "C-S03 transfer pricing general rule opportunity cost",
    "MicroTopic": "Transfer pricing general rule opportunity cost",
    "UniqueConceptKey": "C-S03-transfer-pricing-general-rule-opportunity-cost",
    "LOSTag": "P1-C.1",
    "primaryTheory": "C6",
